// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != c.DEPOSITOR_ACCOUNT());
        vm.prank(caller);
        bool ok = true;
        try c.setL1BlockValues(1, 1, 1, bytes32(0), 1, bytes32(0), 1, 1) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: only depositorAccount passes; bug: any address == DEPOSITOR_ACCOUNT passes, others still fail
        // But caller != DEPOSITOR_ACCOUNT, so caller also != initial depositorAccount (unless changed)
        // The property: a non-DEPOSITOR_ACCOUNT caller must always revert
        assertFalse(ok);
    }
}
